/** Bung manifest thành mảng { path, size } đầy đủ. */
export function listAssets() {
  const out = [];
  for (const dir of Object.keys(MANIFEST)) {
    for (const entry of MANIFEST[dir].split(' ')) {
      const i = entry.lastIndexOf(':');
      out.push({ path: `${dir}/${entry.slice(0, i)}`, size: +entry.slice(i + 1) });
    }
  }
  return out;
}

/** Tra kích thước một đường dẫn logic; trả về -1 nếu không có trong bảng kê. */
export function assetSize(logicalPath) {
  const i = logicalPath.lastIndexOf('/');
  const group = MANIFEST[logicalPath.slice(0, i)];
  if (!group) return -1;
  const name = logicalPath.slice(i + 1);
  for (const entry of group.split(' ')) {
    if (entry.startsWith(name + ':')) return +entry.slice(name.length + 1);
  }
  return -1;
}

/* ─────────────── SỬA LỆCH HOA-THƯỜNG TRONG TÊN FILE ───────────────
   items.json của MU ghi "Item/Wing08.glb" và "Item/sword20.glb", còn trên đĩa
   là "wing08.glb" và "Sword20.glb". Client MU gốc chạy trên Windows — hệ tệp
   ở đó không phân biệt hoa thường nên không ai để ý. Trên Linux, trên máy chủ
   tĩnh và trong zip thì lệch một chữ là 404.

   Đo được: cánh cấp 3 và kiếm Archangel đều 404 vì đúng lý do này, mà không
   có lỗi nào hiện ra — Babylon nuốt lỗi nạp model.

   Bảng kê đã có sẵn TÊN THẬT của cả 11.996 file, nên dùng luôn nó làm bảng
   tra. Chỉ dựng chỉ mục cho thư mục nào thực sự bị hỏi tới, và chỉ khi tên
   đúng y nguyên không có — đường dẫn đúng thì không tốn gì. */

const chiMucThuMuc = new Map();

/**
 * Trả về đường dẫn logic với ĐÚNG hoa thường như trên đĩa.
 * Không tìm thấy thì trả về nguyên đường dẫn đưa vào.
 */
export function suaHoaThuong(logicalPath) {
  const i = logicalPath.lastIndexOf('/');
  if (i < 0) return logicalPath;

  const dir = logicalPath.slice(0, i);
  const name = logicalPath.slice(i + 1);
  const group = MANIFEST[dir];
  if (!group) return logicalPath;

  // Tên đúng y nguyên thì thôi, khỏi dựng chỉ mục.
  if (group.includes(name + ':')) return logicalPath;

  let idx = chiMucThuMuc.get(dir);
  if (!idx) {
    idx = new Map();
    for (const entry of group.split(' ')) {
      const j = entry.lastIndexOf(':');
      const ten = entry.slice(0, j);
      idx.set(ten.toLowerCase(), ten);
    }
    chiMucThuMuc.set(dir, idx);
  }

  const that = idx.get(name.toLowerCase());
  return that ? `${dir}/${that}` : logicalPath;
}
